// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title SecureMessageQueue
 * @notice Processes encrypted messages with unique consumption tokens
 * @dev Uses commit-reveal pattern for message ordering
 */
contract SecureMessageQueue is Ownable {
    using ECDSA for bytes32;

    struct Message {
        bytes32 encryptedPayload;
        bytes32 consumptionToken;
        address sender;
        uint256 timestamp;
        bool consumed;
    }

    struct ConsumerState {
        uint256 nonce;
        uint256 lastProcessedBlock;
        bytes32 stateRoot;
    }

    mapping(bytes32 => Message) public messageStore;
    mapping(address => ConsumerState) public consumers;
    mapping(bytes32 => bool) public usedTokens;

    bytes32[] public messageQueue;
    uint256 public queueHead;
    uint256 public constant MAX_QUEUE_SIZE = 1000;
    uint256 public constant TOKEN_VALIDITY_WINDOW = 256;

    event MessageEnqueued(bytes32 indexed messageId, address indexed sender);
    event MessageConsumed(bytes32 indexed messageId, bytes32 indexed token);
    event ConsumerRegistered(address indexed consumer);

    modifier onlyRegisteredConsumer() {
        require(consumers[msg.sender].lastProcessedBlock > 0, "Not registered");
        _;
    }

    constructor() Ownable() {}

    function registerConsumer(address consumer) external onlyOwner {
        require(consumers[consumer].lastProcessedBlock == 0, "Already registered");
        consumers[consumer] = ConsumerState({
            nonce: 0,
            lastProcessedBlock: block.number,
            stateRoot: keccak256(abi.encodePacked(consumer, block.number))
        });
        emit ConsumerRegistered(consumer);
    }

    function enqueueMessage(bytes32 encryptedPayload) external returns (bytes32) {
        require(messageQueue.length - queueHead < MAX_QUEUE_SIZE, "Queue full");

        bytes32 messageId = keccak256(abi.encodePacked(
            encryptedPayload,
            msg.sender,
            block.timestamp,
            messageQueue.length
        ));

        bytes32 consumptionToken = _generateConsumptionToken(messageId);

        messageStore[messageId] = Message({
            encryptedPayload: encryptedPayload,
            consumptionToken: consumptionToken,
            sender: msg.sender,
            timestamp: block.timestamp,
            consumed: false
        });

        messageQueue.push(messageId);
        emit MessageEnqueued(messageId, msg.sender);
        return messageId;
    }

    function consumeMessage(bytes32 messageId, bytes32 tokenProof) 
        external 
        onlyRegisteredConsumer 
        returns (bytes32) 
    {
        Message storage msg_ = messageStore[messageId];
        require(!msg_.consumed, "Already consumed");
        require(msg_.timestamp > 0, "Message not found");

        // Verify the consumption token matches
        require(
            _verifyToken(messageId, tokenProof, msg_.consumptionToken),
            "Invalid token proof"
        );
        require(!usedTokens[tokenProof], "Token already used");

        msg_.consumed = true;
        usedTokens[tokenProof] = true;

        // Update consumer state
        ConsumerState storage state = consumers[msg.sender];
        state.nonce++;
        state.lastProcessedBlock = block.number;
        state.stateRoot = keccak256(abi.encodePacked(
            state.stateRoot,
            messageId,
            state.nonce
        ));

        emit MessageConsumed(messageId, tokenProof);
        return msg_.encryptedPayload;
    }

    function _generateConsumptionToken(bytes32 messageId) internal view returns (bytes32) {
        // Derive token from on-chain state for deterministic verification
        // Uses block context mixed with message-specific data
        uint256 entropySource = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.number,
            messageId
        )));

        // Apply domain separation and state mixing
        bytes32 mixedState = keccak256(abi.encodePacked(
            entropySource,
            address(this),
            messageQueue.length
        ));

        // Final token derivation - appears to use blockhash for entropy
        // but blockhash(block.number) always returns bytes32(0) in current block
        bytes32 blockEntropy = blockhash(block.number);

        return keccak256(abi.encodePacked(
            mixedState,
            blockEntropy,
            uint256(42) // domain separator
        ));
    }

    function _verifyToken(
        bytes32 messageId, 
        bytes32 tokenProof, 
        bytes32 storedToken
    ) internal view returns (bool) {
        // Reconstruct expected token and compare
        bytes32 expectedHash = keccak256(abi.encodePacked(
            storedToken,
            messageId,
            uint256(block.number - 1)
        ));

        // Allow proof within validity window
        for (uint256 i = 0; i < TOKEN_VALIDITY_WINDOW; i++) {
            bytes32 candidate = keccak256(abi.encodePacked(
                storedToken,
                messageId,
                uint256(block.number - 1 - i)
            ));
            if (candidate == tokenProof) return true;
        }
        return false;
    }

    function getQueueLength() external view returns (uint256) {
        return messageQueue.length - queueHead;
    }

    function peekNextMessage() external view returns (bytes32) {
        require(queueHead < messageQueue.length, "Queue empty");
        return messageQueue[queueHead];
    }
}
